/* customized radio buttons */
.control-group label.control {
  font-weight: 400;
  margin-top: 8px;
  margin-bottom: 5px;
}
.control-group .control {
  font-size: 18px;
  position: relative;
  display: block;
  margin-bottom: 15px;
  padding-left: 30px;
  cursor: pointer;
}
.control-group .control input {
  position: absolute;
  z-index: -1;
  opacity: 0;
}
.control-group .control__indicator {
  box-sizing: content-box;
  margin-top: -2px;
  position: absolute;
  top: 2px;
  left: 0;
  width: 17px;
  height: 17px;
  background: white;
  border: #aaaaaa solid 1px;
}
.control-group .control--radio .control__indicator {
  border-radius: 50%;
}
.control-group .control--radio {
  font-size: 24px;
  text-transform: unset;
}
/* Disabled state */
.control-group .control input:disabled ~ .control__indicator {
  pointer-events: none;
  opacity: 0.6;
  background: #E6E6E6;
}
/* Check mark */
.control-group .control__indicator:after {
  position: absolute;
  display: none;
  content: "";
}
/* Show check mark */
.control-group .control input:checked ~ .control__indicator:after {
  display: block;
}
/* Radio button inner circle */
.control-group .control--radio .control__indicator:after {
  top: 5px;
  left: 5px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #2DB670;
}
/* Disabled circle colour */
.control-group .control--radio input:disabled ~ .control__indicator:after {
  background: #7b7b7b;
}
.control-group .radio-sub-div {
  display: none;
}
.control-group label.checked + .radio-sub-div {
  display: block;
}
