/* Track CSS Start */
.zoom-slider input[type=range] {
  cursor: pointer;
  -webkit-appearance: none;
  width: 100%;
  padding: 4.25px 0;
}
.zoom-slider input[type=range]:focus {
  outline: none;
}
.zoom-slider input[type=range]::-webkit-slider-runnable-track {
  width: 100%;
  height: 2px;
  cursor: pointer;
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
  background: #c5c6c8;
  border-radius: 0px;
  border: 0px solid rgba(0, 0, 0, 0);
}
.zoom-slider input[type=range]::-webkit-slider-thumb {
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
  border: 0px solid rgba(0, 0, 0, 0);
  height: 7px;
  width: 7px;
  border-radius: 4px;
  background: #29ba9c;
  cursor: pointer;
  -webkit-appearance: none;
  margin-top: -2.25px;
}
.zoom-slider input[type=range]::-webkit-slider-thumb:hover {
  height: 10px;
  cursor: grabbing;
  cursor: -webkit-grabbing;
  cursor: -ms-grabbing;
}
.zoom-slider input[type=range]:focus::-webkit-slider-runnable-track {
  background: #c8c9ca;
}
.zoom-slider input[type=range]::-moz-range-track {
  width: 100%;
  height: 2px;
  cursor: pointer;
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
  background: #c5c6c8;
  border-radius: 0px;
  border: 0px solid rgba(0, 0, 0, 0);
}
.zoom-slider input[type=range]::-moz-range-thumb {
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
  border: 0px solid rgba(0, 0, 0, 0);
  height: 7px;
  width: 7px;
  border-radius: 4px;
  background: #29ba9c;
  cursor: pointer;
}
.zoom-slider input[type=range]::-moz-range-thumb:hover {
  height: 10px;
  cursor: grabbing;
  cursor: -webkit-grabbing;
  cursor: -ms-grabbing;
}
.zoom-slider input[type=range]::-ms-track {
  width: 100%;
  height: 2px;
  cursor: pointer;
  background: transparent;
  border-color: transparent;
  color: transparent;
}
.zoom-slider input[type=range]::-ms-fill-lower {
  background: #c2c3c6;
  border: 0px solid rgba(0, 0, 0, 0);
  border-radius: 0px;
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
}
.zoom-slider input[type=range]::-ms-fill-upper {
  background: #c5c6c8;
  border: 0px solid rgba(0, 0, 0, 0);
  border-radius: 0px;
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
}
.zoom-slider input[type=range]::-ms-thumb {
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0), 0px 0px 0px rgba(13, 13, 13, 0);
  border: 0px solid rgba(0, 0, 0, 0);
  height: 7px;
  width: 7px;
  border-radius: 4px;
  background: #29ba9c;
  cursor: pointer;
  height: 2px;
}
.zoom-slider input[type=range]:focus::-ms-fill-lower {
  background: #c5c6c8;
}
.zoom-slider input[type=range]:focus::-ms-fill-upper {
  background: #c8c9ca;
}
