.joint-link.joint-theme-material .connection-wrap:hover{opacity:.4;stroke-opacity:.4}


.joint-link.joint-theme-material .connection{stroke-linejoin:round}


.joint-link.joint-theme-material .link-tools .tool-remove circle{fill:#c64242}


.joint-link.joint-theme-material .link-tools .tool-remove path{fill:#fff}


.joint-link.joint-theme-material .marker-vertex{fill:#d0d8e8}


.joint-link.joint-theme-material .marker-vertex:hover{fill:#5fa9ee;stroke:none}


.joint-link.joint-theme-material .marker-arrowhead{fill:#d0d8e8}


.joint-link.joint-theme-material .marker-arrowhead:hover{fill:#5fa9ee;stroke:none}


.joint-link.joint-theme-material .marker-vertex-remove-area{fill:#5fa9ee}


.joint-link.joint-theme-material .marker-vertex-remove{fill:#fff}


.joint-link.joint-theme-modern .connection-wrap{stroke:#000;stroke-width:15;stroke-linecap:round;stroke-linejoin:round;opacity:0;cursor:move}


.joint-link.joint-theme-modern .connection-wrap:hover{opacity:.4;stroke-opacity:.4}


.joint-link.joint-theme-modern .connection{stroke-linejoin:round}


.joint-link.joint-theme-modern .link-tools .tool-remove circle{fill:red}


.joint-link.joint-theme-modern .link-tools .tool-remove path{fill:#fff}


.joint-link.joint-theme-modern .marker-vertex{fill:#1abc9c}


.joint-link.joint-theme-modern .marker-vertex:hover{fill:#34495e;stroke:none}


.joint-link.joint-theme-modern .marker-arrowhead{fill:#1abc9c}


.joint-link.joint-theme-modern .marker-arrowhead:hover{fill:#f39c12;stroke:none}


.joint-link.joint-theme-modern .marker-vertex-remove{fill:#fff}


.joint-paper-scroller{position:relative;overflow:scroll;box-sizing:border-box;width:100%;height:100%}


.joint-paper-scroller>.paper-scroller-background{margin:0;position:relative;display:inline-block;vertical-align:top}


.joint-paper-scroller .joint-paper{margin:0;position:absolute;display:inline-block}


.joint-paper-scroller .joint-paper>svg{display:block}


.joint-paper-scroller[data-cursor=grab]{cursor:all-scroll;cursor:-webkit-grab;cursor:grab}


.joint-paper-scroller[data-cursor=grab].is-panning{cursor:-webkit-grabbing;cursor:grabbing}


.joint-paper-scroller.joint-theme-dark>.paper-scroller-background{background:#18191b}


.joint-paper-scroller.joint-theme-dark .joint-paper{border:1px dotted #fefefe}


.joint-paper-scroller.joint-theme-material{background-color:#f3f5fa}


.joint-paper-scroller.joint-theme-modern{background-color:#f6f6f6}


.joint-paper-scroller.joint-theme-modern .joint-paper{box-shadow:0 0 2px #d3d3d3}


.joint-selection{display:none;touch-action:none}


.joint-selection.lasso{display:block;position:absolute;opacity:.3;overflow:visible}


.joint-selection.selected{display:block;background-color:transparent;opacity:1;cursor:move;position:static;height:0!important}


.selection-box{position:absolute;padding-right:5px;padding-bottom:5px;margin-top:-4px;margin-left:-4px;box-sizing:content-box}


.selection-wrapper{position:absolute;margin-left:-6px;margin-top:-6px;padding-right:9px;padding-bottom:9px;pointer-events:none}


.selection-wrapper[data-selection-length="0"],.selection-wrapper[data-selection-length="1"]{display:none}


.joint-selection .box{position:absolute;top:100%;margin-top:30px;left:-20px;right:-20px;text-align:center;line-height:14px;border-radius:6px;padding:6px}


.joint-selection .handle.se{bottom:-25px;right:-25px}


.joint-selection .handle.nw{top:-21px;left:-25px}


.joint-selection .handle.n{top:-22px;left:50%;margin-left:-10px}


.joint-selection .handle.e{right:-25px;top:calc(50% - 10px)}


.joint-selection .handle.ne{top:-21px;right:-25px}


.joint-selection .handle.w{left:-25px;top:50%;margin-top:-10px}


.joint-selection .handle.sw{bottom:-25px;left:-25px}


.joint-selection .handle.s{bottom:-24px;left:50%;margin-left:-10px}


.joint-selection .handle{position:absolute;pointer-events:auto;width:20px;height:20px;background-size:20px 20px;background-repeat:no-repeat;-moz-user-select:none;-webkit-user-select:none;-ms-user-select:none;user-select:none;-webkit-user-drag:none;user-drag:none;cursor:pointer}


.joint-selection .remove{cursor:pointer}


.joint-selection .rotate{cursor:move}


.joint-selection .box:empty{display:none}


