.joint-stencil.joint-theme-material.searchable.is-focused .search-wrap:after{z-index:1000;left:0;width:90%}


.joint-stencil.joint-theme-material.searchable .groups-toggle{height:30px}


.joint-stencil.joint-theme-modern{color:#c6c7e2;background:#383b61}


.joint-stencil.joint-theme-modern>.content{position:absolute}


.joint-stencil.joint-theme-modern.searchable>.content{top:48px}


.joint-stencil.joint-theme-modern.collapsible>.content{top:30px}


.joint-stencil.joint-theme-modern.searchable.collapsible>.content{top:70px}


.joint-stencil.joint-theme-modern.not-found:after{position:absolute}


.joint-stencil.joint-theme-modern.not-found.searchable.collapsible:after{top:80px}


.joint-stencil.joint-theme-modern.not-found.searchable:after{top:60px}


.joint-stencil.joint-theme-modern .group{height:auto;padding:0;margin-bottom:1px;transition:none}


.joint-stencil.joint-theme-modern .group>.joint-elements{background:#4a4d6e;margin:0}


.joint-stencil.joint-theme-modern .group.closed{height:auto;max-height:31px}


.joint-stencil.joint-theme-modern input[type=search]{-webkit-appearance:textfield}


.joint-stencil.joint-theme-modern input[type=search]::-webkit-search-cancel-button,.joint-stencil.joint-theme-modern input[type=search]::-webkit-search-decoration{-webkit-appearance:none}


.joint-stencil.joint-theme-modern .group>.group-label,.joint-stencil.joint-theme-modern .groups-toggle>.group-label{position:relative;left:0;width:100%;height:31px;line-height:31px;color:#9093b1;font-size:12px;font-weight:700;text-transform:uppercase;box-sizing:border-box}


.joint-stencil.joint-theme-modern .group>.group-label{padding:0 5px 0 34px;background:#424568}


.joint-stencil.joint-theme-modern .groups-toggle>.group-label{position:absolute}


.joint-stencil.joint-theme-modern .group>.group-label:hover,.joint-stencil.joint-theme-modern .groups-toggle>.group-label:hover{color:#d8d8ec}


.joint-stencil.joint-theme-modern .group>.group-label:before,.joint-stencil.joint-theme-modern .groups-toggle .btn-collapse,.joint-stencil.joint-theme-modern .groups-toggle .btn-expand{position:absolute;left:5px;top:6px;display:block;width:19px;height:19px;background-color:transparent;background-position:0 0;background-repeat:no-repeat;border:none;content:' ';margin:0;padding:0}


.joint-stencil.joint-theme-modern .groups-toggle .btn{line-height:30px;color:transparent;position:relative;display:inline-block}


.joint-stencil.joint-theme-modern .groups-toggle .btn:focus{outline:0}


.joint-stencil.joint-theme-modern .groups-toggle .btn:hover{cursor:pointer}


